use crate::session::PersistedWorkspaceSession;
use crate::terminal::TerminalSignal;
use crate::worktree::WorktreeIdentity;
use serde::{Deserialize, Serialize};
use std::borrow::Cow;

pub const DAEMON_PROTOCOL_VERSION: u32 = 1;

pub mod base64_serde {
    use base64::{engine::general_purpose::STANDARD, Engine as _};
    use serde::{de::Error as _, Deserialize, Deserializer, Serializer};
    use std::borrow::Cow;

    pub fn serialize<S, T>(bytes: &T, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
        T: AsRef<[u8]>,
    {
        serializer.serialize_str(&STANDARD.encode(bytes.as_ref()))
    }

    pub fn deserialize<'de, D, T>(deserializer: D) -> Result<T, D::Error>
    where
        D: Deserializer<'de>,
        T: From<Vec<u8>>,
    {
        let s = Cow::<'de, str>::deserialize(deserializer)?;
        let decoded = STANDARD.decode(s.as_bytes()).map_err(D::Error::custom)?;
        Ok(T::from(decoded))
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum DaemonRequest {
    Handshake {
        version: u32,
    },
    Ping,
    Spawn {
        workspace_id: String,
        worktree: Option<WorktreeIdentity>,
        cols: u16,
        rows: u16,
    },
    Write {
        session_id: String,
        #[serde(with = "base64_serde")]
        data: Vec<u8>,
    },
    Resize {
        session_id: String,
        cols: u16,
        rows: u16,
    },
    Signal {
        session_id: String,
        signal: TerminalSignal,
    },
    Close {
        session_id: String,
    },
    ListSessions,
    Attach {
        session_id: String,
    },
    SaveSession {
        session: PersistedWorkspaceSession,
    },
    LoadSession,
    ClearSession,
    Shutdown,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum DaemonResponse {
    HandshakeOk {
        version: u32,
        pid: u32,
    },
    Pong,
    SpawnOk {
        session_id: String,
    },
    WriteOk,
    ResizeOk,
    SignalOk,
    CloseOk,
    ListSessionsOk {
        sessions: Vec<String>,
    },
    AttachOk {
        #[serde(with = "base64_serde")]
        history: Vec<u8>,
    },
    SaveSessionOk,
    LoadSessionOk {
        session: Option<PersistedWorkspaceSession>,
    },
    ClearSessionOk,
    Error {
        message: String,
    },
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum DaemonStreamMessage<'a> {
    Output {
        session_id: Cow<'a, str>,
        #[serde(with = "base64_serde")]
        data: Cow<'a, [u8]>,
    },
    Lagged {
        session_id: Cow<'a, str>,
        #[serde(with = "base64_serde")]
        history: Cow<'a, [u8]>,
    },
    Exit {
        session_id: Cow<'a, str>,
        exit_code: Option<i32>,
    },
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_daemon_stream_message_compact_base64_encoding() {
        let output = DaemonStreamMessage::Output {
            session_id: Cow::Borrowed("s1"),
            data: Cow::Borrowed(b"hello world"),
        };
        let json = serde_json::to_string(&output).expect("serialize output");

        // Contract: must NOT serialize raw bytes as JSON number arrays [104, 101, ...]
        assert!(
            !json.contains('['),
            "Stream output must not contain JSON number arrays: {json}"
        );
        assert!(
            json.contains(r#""data":"aGVsbG8gd29ybGQ=""#),
            "Expected base64-encoded string for data: {json}"
        );

        let deserialized: DaemonStreamMessage =
            serde_json::from_str(&json).expect("deserialize output");
        match deserialized {
            DaemonStreamMessage::Output { session_id, data } => {
                assert_eq!(session_id, "s1");
                assert_eq!(&data[..], b"hello world");
            }
            _ => panic!("Expected Output variant"),
        }
    }

    #[test]
    fn test_daemon_stream_message_lagged_and_exit_roundtrip() {
        let lagged = DaemonStreamMessage::Lagged {
            session_id: Cow::Borrowed("s2"),
            history: Cow::Borrowed(b"history bytes"),
        };
        let json = serde_json::to_string(&lagged).expect("serialize lagged");
        assert!(!json.contains('['));
        assert!(json.contains(r#""history":"aGlzdG9yeSBieXRlcw==""#));

        let deserialized: DaemonStreamMessage =
            serde_json::from_str(&json).expect("deserialize lagged");
        assert_eq!(
            deserialized,
            DaemonStreamMessage::Lagged {
                session_id: Cow::Owned("s2".to_string()),
                history: Cow::Owned(b"history bytes".to_vec()),
            }
        );

        let exit = DaemonStreamMessage::Exit {
            session_id: Cow::Borrowed("s3"),
            exit_code: Some(0),
        };
        let exit_json = serde_json::to_string(&exit).expect("serialize exit");
        let deserialized_exit: DaemonStreamMessage =
            serde_json::from_str(&exit_json).expect("deserialize exit");
        assert_eq!(
            deserialized_exit,
            DaemonStreamMessage::Exit {
                session_id: Cow::Owned("s3".to_string()),
                exit_code: Some(0),
            }
        );
    }

    #[test]
    fn test_daemon_request_write_and_response_attach_base64() {
        let write_req = DaemonRequest::Write {
            session_id: "term-1".to_string(),
            data: b"ls -la\n".to_vec(),
        };
        let json = serde_json::to_string(&write_req).expect("serialize write");
        assert!(!json.contains('['));
        assert!(json.contains(r#""data":"bHMgLWxhCg==""#));

        let deserialized_req: DaemonRequest =
            serde_json::from_str(&json).expect("deserialize write");
        match deserialized_req {
            DaemonRequest::Write { session_id, data } => {
                assert_eq!(session_id, "term-1");
                assert_eq!(data, b"ls -la\n");
            }
            _ => panic!("Expected Write variant"),
        }

        let attach_resp = DaemonResponse::AttachOk {
            history: b"initial prompt $ ".to_vec(),
        };
        let resp_json = serde_json::to_string(&attach_resp).expect("serialize attach resp");
        assert!(!resp_json.contains('['));
        assert!(resp_json.contains(r#""history":"aW5pdGlhbCBwcm9tcHQgJCA="#));

        let deserialized_resp: DaemonResponse =
            serde_json::from_str(&resp_json).expect("deserialize attach resp");
        match deserialized_resp {
            DaemonResponse::AttachOk { history } => {
                assert_eq!(history, b"initial prompt $ ");
            }
            _ => panic!("Expected AttachOk variant"),
        }
    }
}

// allow: SIZE_OK — daemon IPC server implementation with routing, session persistence offloading, and streaming
use crate::daemon::protocol::{
    DaemonRequest, DaemonResponse, DaemonStreamMessage, DAEMON_PROTOCOL_VERSION,
};
use crate::remote::server::start_remote_server;
use crate::remote::state::{RemoteGatewayConfig, RemoteGatewayState, RemoteNetworkMode};
use crate::session::{clear_session_from_path, load_session_from_path, save_session_to_path};
use crate::terminal::{PtyManager, TerminalOutputHub, TerminalService};
use crate::worktree::WorkspaceRegistry;
use portable_pty::CommandBuilder;
use std::borrow::Cow;
use std::fs::{self, OpenOptions};
use std::os::unix::fs::PermissionsExt;
use std::path::PathBuf;
